// Holds a PA_Variable the plugin owns (an engine-returned copy or a value it
// created) and clears it on scope exit, including when SOCI throws. Values
// returned by an engine call are only owned if that call succeeded, so the
// error is captured immediately after the call.
struct owned_variable {
    PA_Variable v;
    bool owned;
    owned_variable() : v(PA_CreateVariable(eVK_Undefined)), owned(true) {}
    explicit owned_variable(PA_Variable value) : v(value), owned(PA_GetLastError() == eER_NoErr) {
        if(!owned) {
            v = PA_CreateVariable(eVK_Undefined);
        }
    }
    ~owned_variable() {
        if(owned) {
            PA_ClearVariable(&v);
        }
    }
    owned_variable(const owned_variable&) = delete;
    owned_variable& operator=(const owned_variable&) = delete;
};

// This header's ob_set_* family only covers JSON-representable property
// types (text, number, bool, null, object, collection, picture) -- there is
// no raw-binary/BLOB setter, since JSON itself has no binary type. Base64
// text is the standard way to carry binary data through a JSON-shaped
// object, so BLOB columns are exposed to 4D as Base64 text via ob_set_s
// rather than as a native BLOB property.
static std::string base64_encode(const unsigned char *data, size_t len) {
    static const char alphabet[] =
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz"
        "0123456789+/";
    std::string out;
    out.reserve(((len + 2) / 3) * 4);
    size_t i = 0;
    while (i + 3 <= len) {
        unsigned int n = ((unsigned int)data[i] << 16) | ((unsigned int)data[i + 1] << 8) | (unsigned int)data[i + 2];
        out += alphabet[(n >> 18) & 0x3F];
        out += alphabet[(n >> 12) & 0x3F];
        out += alphabet[(n >> 6) & 0x3F];
        out += alphabet[n & 0x3F];
        i += 3;
    }
    size_t rem = len - i;
    if (rem == 1) {
        unsigned int n = (unsigned int)data[i] << 16;
        out += alphabet[(n >> 18) & 0x3F];
        out += alphabet[(n >> 12) & 0x3F];
        out += '=';
        out += '=';
    } else if (rem == 2) {
        unsigned int n = ((unsigned int)data[i] << 16) | ((unsigned int)data[i + 1] << 8);
        out += alphabet[(n >> 18) & 0x3F];
        out += alphabet[(n >> 12) & 0x3F];
        out += alphabet[(n >> 6) & 0x3F];
        out += '=';
    }
    return out;
}

static void toStr(PA_Unistring* from, std::string& to) {
    C_TEXT t;
    t.setUTF16String((const PA_Unichar *)from->fString, from->fLength);
    CUTF8String u8;
    t.copyUTF8String(&u8);
    to = std::string((const char *)u8.c_str(), u8.length());
}

static bool is_blob_class(PA_ObjectRef blob) {
    if(blob == NULL) {
        return false;
    }
    bool is_blob_object = false;
    PA_Variable cbparams[1];
    cbparams[0] = PA_CreateVariable(eVK_Object);
    PA_SetObjectVariable(&cbparams[0], blob);
    owned_variable classVar(PA_ExecuteCommandByID(1730 /*OB Class*/, cbparams, 1));
    //do not clear cbparams[0], it borrows the caller's blob
    PA_ObjectRef _class = PA_GetObjectVariable(classVar.v);
    C_TEXT t;
    t.setUTF8String((const uint8_t *)"name", 4);
    CUTF16String _name;
    t.copyUTF16String(&_name);
    PA_Unistring name = PA_CreateUnistring((PA_Unichar *)_name.c_str());
    if(_class != NULL && PA_HasObjectProperty(_class, &name)) {
        owned_variable v(PA_GetObjectProperty(_class, &name));
        if(PA_GetVariableKind(v.v)==eVK_Unistring) {
            PA_Unistring n = PA_GetStringVariable(v.v);
            t.setUTF16String(&n);
            CUTF8String _n;
            t.copyUTF8String(&_n);
            if(_n == (const uint8_t *)"Blob") {
                is_blob_object = true;
            }
        }
    }
    PA_DisposeUnistring(&name);
    return is_blob_object;
}

static PA_long32 blob_size(PA_ObjectRef blob) {
    if(blob == NULL) {
        return 0L;
    }
    if(!is_blob_class(blob)) {
        return 0L;
    }
    PA_Variable cbparams[1];
    cbparams[0] = PA_CreateVariable(eVK_Object);
    PA_SetObjectVariable(&cbparams[0], blob);
    PA_long32 size = PA_GetLongintVariable(PA_ExecuteCommandByID(605 /*BLOB size*/, cbparams, 1));
    //do not clear cbparams[0], it borrows the caller's blob
    return size;
}

static void get_blob_data(PA_ObjectRef blob, std::vector<unsigned char>& buf) {
    
    PA_long32 size = blob_size(blob);
    
    if(size != 0) {
        PA_Variable cbparams[5];
        cbparams[0] = PA_CreateVariable(eVK_Object);
        cbparams[1] = PA_CreateVariable(eVK_Undefined);
        PA_SetObjectVariable(&cbparams[0], blob);
        PA_SetBlobVariable(&cbparams[1], NULL, 0);
        PA_ExecuteCommandByID(532 /*VARIABLE TO BLOB*/, cbparams, 2);
        cbparams[0] = cbparams[1];
        cbparams[1] = PA_CreateVariable(eVK_Blob);
        cbparams[2] = PA_CreateVariable(eVK_Longint);
        cbparams[3] = PA_CreateVariable(eVK_Longint);
        cbparams[4] = PA_CreateVariable(eVK_Longint);
        PA_SetLongintVariable(& cbparams[2], 37);
        PA_SetLongintVariable(& cbparams[3], 0L);
        PA_SetLongintVariable(& cbparams[4], size);
        PA_ExecuteCommandByID(558 /*COPY BLOB*/, cbparams, 5);
        buf.resize(size);
        PA_GetBlobVariable(cbparams[1], buf.data());
        PA_ClearVariable(&cbparams[2]);
        PA_ClearVariable(&cbparams[3]);
        PA_ClearVariable(&cbparams[4]);
        PA_ClearVariable(&cbparams[0]); //release VARIABLE TO BLOB scratch output (plugin-owned, not the caller's blob)
        PA_ClearVariable(&cbparams[1]); //release COPY BLOB scratch output (plugin-owned)
    }
}

static void SOCI(PA_PluginParameters params) {

    soci_backend_t backend = (soci_backend_t)PA_GetLongParameter(params, 1);
    soci_mode_t mode = (soci_mode_t)PA_GetLongParameter(params, 5);
    PA_CollectionRef statements = PA_GetCollectionParameter(params, 3);
    PA_CollectionRef bindings = PA_GetCollectionParameter(params, 4);

    PA_ObjectRef status = PA_CreateObject();
    
    PackagePtr pParams = (PackagePtr)params->fParameters;

    C_TEXT p2;
    p2.fromParamAtIndex(pParams, 2);
    CUTF8String connection;
    p2.copyUTF8String(&connection);
    
    ob_set_b(status, L"success", false);
            
    soci::session sql;
    PA_CollectionRef results = PA_CreateCollection();
    
    try {
        switch (backend) {
            case soci_backend_odbc:
            {
                soci::connection_parameters parameters(soci::odbc, (const char *)connection.c_str());
                PA_ObjectRef options = PA_GetObjectParameter(params, 6);
                if(options != NULL) {
                    CUTF8String stringValue;
                    if(ob_get_a(options, L"odbc_option_driver_complete", &stringValue)) {
                        parameters.set_option(soci::odbc_option_driver_complete, (const char*)stringValue.c_str());
                    }
                }
                sql.open(parameters);
            }
                break;
            case soci_backend_mysql:
                sql.open(soci::mysql, (const char *)connection.c_str());
                break;
            case soci_backend_postgresql:
                sql.open(soci::postgresql, (const char *)connection.c_str());
                break;
            case soci_backend_sqlite3:
                sql.open(soci::sqlite3, (const char *)connection.c_str());
                break;
        }

        
        std::unique_ptr<soci::transaction> tr;
        if(mode == soci_mode_transaction) {
            tr = std::make_unique<soci::transaction>(sql);
        }

        if(statements != NULL) {
            
            unsigned int countLines = PA_GetCollectionLength(statements);
            unsigned int countBindings = bindings == NULL ? 0 : PA_GetCollectionLength(bindings);
            
            for(unsigned int l = 0; l < countLines; ++l) {
                owned_variable v(PA_GetCollectionElement(statements, l));
                if(PA_GetVariableKind(v.v) == eVK_Unistring) {
                    
                    PA_Unistring _statement = PA_GetStringVariable(v.v);
                    std::string statement;
                    toStr(&_statement, statement);
                      
                    soci::statement st(sql);
                    soci::row r;
                    
                    std::map<std::string, std::string>bind_dt_string;
                    std::map<std::string, PA_long32>bind_dt_integer;
                    std::map<std::string, double>bind_dt_double;
                    std::map<std::string, std::unique_ptr<soci::blob> >bind_dt_blob;

                    int null_value = 0;
                    soci::indicator null_indicator = soci::i_null;
                    
                    st.alloc();
                    st.prepare(statement);
                    st.exchange(soci::into(r));
                    
                    if(l < countBindings) {
                        owned_variable bindingType(PA_GetCollectionElement(bindings, l));
                        switch (PA_GetVariableKind(bindingType.v)) {
                            case eVK_Object:
                            {
                                PA_ObjectRef binding = PA_GetObjectVariable(bindingType.v);
                                PA_Variable cbparams[1];
                                cbparams[0] = PA_CreateVariable(eVK_Object);
                                PA_SetObjectVariable(&cbparams[0], binding);
                                owned_variable keysVar(PA_ExecuteCommandByID(1719 /*OB Keys*/, cbparams, 1));
                                //do not clear cbparams[0], it borrows binding from bindingType
                                PA_CollectionRef keys = PA_GetCollectionVariable(keysVar.v);
                                if(keys != NULL) {
                                    unsigned int count = PA_GetCollectionLength(keys);
                                    for(unsigned int i = 0; i < count; ++i) {
                                        owned_variable key(PA_GetCollectionElement(keys, i));
                                        if(PA_GetVariableKind(key.v) == eVK_Unistring) {
                                            PA_Unistring _name = PA_GetStringVariable(key.v);
                                            std::string name;
                                            toStr(&_name, name);
                                            owned_variable property(PA_GetObjectProperty(binding, &_name));
                                            PA_Variable value = property.v;
                                            PA_VariableKind type = PA_GetObjectPropertyType(binding, &_name);
                                            switch (type) {
                                                case eVK_Real:
                                                {
                                                    double _value = PA_GetRealVariable(value);
                                                    bind_dt_double[name] = _value;
                                                    st.exchange(soci::use(bind_dt_double[name], name));
                                                }
                                                    break;
                                                case eVK_Longint:
                                                case eVK_Integer:
                                                {
                                                    PA_long32 _value = PA_GetLongintVariable(value);
                                                    bind_dt_integer[name] = _value;
                                                    st.exchange(soci::use(bind_dt_integer[name], name));
                                                }
                                                    break;
                                                case eVK_Time:
                                                {
                                                    PA_long32 _value = PA_GetTimeVariable(value);
                                                    bind_dt_integer[name] = _value;
                                                    st.exchange(soci::use(bind_dt_integer[name], name));
                                                }
                                                    break;
                                                case eVK_Boolean:
                                                {
                                                    int _value = PA_GetBooleanVariable(value);
                                                    bind_dt_integer[name] = _value;
                                                    st.exchange(soci::use(bind_dt_integer[name], name));
                                                }
                                                    break;
                                                case eVK_Null:
                                                {
                                                    st.exchange(soci::use(null_value, null_indicator, name));
                                                }
                                                    break;
                                                case eVK_Unistring:
                                                {
                                                    PA_Unistring __value = PA_GetStringVariable(value);
                                                    std::string _value;
                                                    toStr(&__value, _value);
                                                    bind_dt_string[name] = _value;
                                                    st.exchange(soci::use(bind_dt_string[name], name));
                                                }
                                                    break;
                                                case eVK_Object:
                                                {
                                                    PA_ObjectRef _value = PA_GetObjectVariable(value);
                                                    std::vector<unsigned char> buf(0);
                                                    get_blob_data(_value, buf);
                                                    bind_dt_blob[name] = std::make_unique<soci::blob>(sql);
                                                    bind_dt_blob[name]->write(0, (const char *)buf.data(), buf.size());
                                                    st.exchange(soci::use(*bind_dt_blob[name], name));
                                                }
                                                    break;
                                                case eVK_Blob:
                                                    //4D.Blob is an object(38)
                                                    break;
                                                case eVK_Date:
                                                {
                                                    //need to store as ISO date
                                                    short dd, mm, yyyy;
                                                    PA_GetDateVariable(value, &dd, &mm, &yyyy);
                                                    char _value[11]; // "YYYY-MM-DD" + null terminator
                                                    snprintf(_value, 11, "%04d-%02d-%02d", yyyy, mm, dd);
                                                    bind_dt_string[name] = _value;
                                                    st.exchange(soci::use(bind_dt_string[name], name));
                                                }
                                                    break;
                                                default:
                                                    break;
                                            }
                                        }
                                    }
                                }
                            }
                                break;
                            default:
                                break;
                        }
                    }
                    
                    st.define_and_bind();
                    st.execute();
                    
                    owned_variable result;
                    PA_CollectionRef _result = PA_CreateCollection();
                    PA_SetCollectionVariable(&result.v, _result);
                    while (st.fetch()) {
                        owned_variable col;
                        PA_ObjectRef _col = PA_CreateObject();
                        PA_SetObjectVariable(&col.v, _col);
                        
                        for (std::size_t i = 0; i < r.size(); ++i) {

                            auto row_properties = r.get_properties(i);
                            std::string col_name = row_properties.get_name();
                            
                            if (r.get_indicator(i) == soci::i_null) {
                                ob_set_0(_col, col_name.c_str());
                            }else{
                                soci::data_type col_type = row_properties.get_data_type();
                                /*
                                 dt_string, dt_date, dt_double, dt_integer, dt_long_long, dt_unsigned_long_long,
                                 dt_blob, dt_xml
                                 */
                                switch (col_type) {
                                    case soci::dt_string:
                                    case soci::dt_xml:
                                    {
                                        std::string value = r.get<std::string>(i);
                                        ob_set_s(_col, col_name.c_str(), value.c_str());
                                    }
                                        break;
                                    case soci::dt_date:
                                    {
                                        std::tm t = r.get<std::tm>(i);
                                        char iso[11]; // "YYYY-MM-DD" + null terminator
                                        snprintf(iso, 11, "%04d-%02d-%02d", t.tm_year + 1900, t.tm_mon + 1, t.tm_mday);
                                        ob_set_s(_col, col_name.c_str(), iso);
                                    }
                                        break;
                                    case soci::dt_double:
                                    {
                                        double value = r.get<double>(i);
                                        ob_set_n(_col, col_name.c_str(), value);
                                    }
                                        break;
                                    case soci::dt_integer:
                                    {
                                        int value = r.get<int>(i);
                                        ob_set_n(_col, col_name.c_str(), value);
                                    }
                                        break;
                                    case soci::dt_long_long:
                                    {
                                        std::string value = std::to_string(r.get<long long>(i));
                                        ob_set_s(_col, col_name.c_str(), value.c_str());
                                    }
                                        break;
                                    case soci::dt_unsigned_long_long:
                                    {
                                        std::string value = std::to_string(r.get<unsigned long long>(i));
                                        ob_set_s(_col, col_name.c_str(), value.c_str());
                                    }
                                        break;
                                    case soci::dt_blob:
                                    {
                                        std::string value = r.get<std::string>(i);
                                        std::string b64 = base64_encode((const unsigned char *)value.data(), value.size());
                                        ob_set_s(_col, col_name.c_str(), b64.c_str());
                                    }
                                        break;
                                }
                            }
                        }
                        PA_SetCollectionElement(_result, PA_GetCollectionLength(_result), col.v);
                    }
                    PA_SetCollectionElement(results, l, result.v);
                }//statement
            }//l (lines)
        }
        
        if(mode == soci_mode_transaction) {
            tr->commit();
            tr.reset(); // destroy transaction object
        }
        
        ob_set_b(status, L"success", true);
        ob_set_c(status, L"results", results);
        
    } catch (const std::exception& e) {
        ob_set_s(status, "errorMessage", e.what());
        ob_set_b(status, L"success", false);
        ob_set_c(status, L"results", results); //attach whatever statements already completed before the error, instead of orphaning them
    }
    PA_ReturnObject(params, status);
}
